query:
// 01 - VALIDASI DATA MOVIELENS
 // Memeriksa jumlah film, user, dan rating

MATCH (m:Movie)-[r:Rating]->(u:User)
RETURN
    count(r) AS totalRating,
    count(DISTINCT m) AS totalMovie,
    count(DISTINCT u) AS totalUser,
    min(r.rating) AS ratingMinimum,
    max(r.rating) AS ratingMaksimum,
    avg(r.rating) AS rataRataRating;

// Memeriksa distribusi rating

MATCH (:Movie)-[r:Rating]->(:User)
RETURN
    r.rating AS nilaiRating,
    count(r) AS jumlahRating
ORDER BY nilaiRating ASC;

// menghitung Node similarity (kemiripan movie based on rating) dengan bobot score 

CALL gds.nodeSimilarity.write(
     'moviePositiveRatings',{
        similarityMetric : 'COSINE',
        similarityCutoff : 0.1,
        topK :20, 
        writeRelationshipType: 'SIMILAR_TO', 
        writeProperty: 'score'}
)
YIELD
    nodesCompared,
    relationshipsWritten
RETURN
    nodesCompared,
    relationshipsWritten
;

// Membuat relations 

CALL gds.graph.project(
    'movieSimilarityGraph',
    'Movie',
    {
        SIMILAR_TO: {
            type: 'SIMILAR_TO',
            orientation: 'UNDIRECTED',
            properties: ['score']
        }
    }
)
YIELD graphName, nodeCount, relationshipCount
RETURN graphName, nodeCount, relationshipCount;
